  <footer>Built by an agent, supervised by humans. 2026 · The Human-in-the-Loop</footer>

  <script>
    (() => {
      const button = document.getElementById("theme-toggle");
      const icon = button.querySelector(".toggle-icon");
      const label = button.querySelector(".toggle-label");

      function updateButton(theme) {
        const switchTo = theme === "dark" ? "light" : "dark";
        button.setAttribute("aria-label", `Switch to ${switchTo} mode`);
        icon.textContent = theme === "dark" ? "☀" : "☾";
        label.textContent = theme === "dark" ? "Day mode" : "Night mode";
      }

      updateButton(document.documentElement.getAttribute("data-theme"));

      button.addEventListener("click", () => {
        const nextTheme = document.documentElement.getAttribute("data-theme") === "dark" ? "light" : "dark";
        document.documentElement.setAttribute("data-theme", nextTheme);
        try {
          localStorage.setItem("upb-theme", nextTheme);
        } catch (_) {
          // Theme still changes for this visit if storage is unavailable.
        }
        updateButton(nextTheme);
      });
    })();
  </script>
</body>
